const r = await tools.exec_command({cmd:"python - <<'PY'
import numpy as np
from PIL import Image
im=np.array(Image.open('/app/target.png').convert('L'))
b=(im<100)
# Zhang-Suen thinning
x=b.copy(); H,W=x.shape
changed=True; it=0
while changed and it<100:
 changed=False; it+=1
 for phase in (0,1):
  p=np.pad(x,1)
  n=[p[:-2,1:-1],p[:-2,2:],p[1:-1,2:],p[2:,2:],p[2:,1:-1],p[2:,:-2],p[1:-1,:-2],p[:-2,:-2]]
  neigh=sum(a.astype(np.uint8) for a in n)
  trans=np.zeros_like(x,dtype=np.uint8)
  for i in range(8): trans+=((~n[i])&n[(i+1)%8]).astype(np.uint8)
  cond=(x)&(neigh>=2)&(neigh<=6)&(trans==1)
  if phase==0: cond &= ~(n[0]&n[2]&n[4]) & ~(n[2]&n[4]&n[6])
  else: cond &= ~(n[0]&n[2]&n[6]) & ~(n[0]&n[4]&n[6])
  if cond.any(): x[cond]=0; changed=True
print('iterations',it)
# output skeleton view
out=np.full((H,W),245,np.uint8);out[x]=0
Image.fromarray(out).crop((250,180,810,820)).resize((840,960)).save('/app/output/skeleton.png')
# degrees with 8-neighbors
p=np.pad(x,1); deg=np.zeros_like(x,np.uint8)
for dy in range(3):
 for dx in range(3):
  if (dy,dx)!=(1,1):deg+=p[dy:dy+H,dx:dx+W]
# cluster endpoints by coords print
for label, mask in [('end',x&(deg==1)),('junction',x&(deg>=3))]:
 yy,xx=np.where(mask); pts=list(zip(xx,yy)); print(label,len(pts),pts[:250])
PY",yield_time_ms:30000,max_output_tokens:5000});
text(r.output);
const i=await tools.view_image({path:"/app/output/skeleton.png"}); image(i.image_url);

